// RigNotificationSettingUpdateValidator is the rules for changing one that
// already exists: what the schema cannot express.
//
// One optional function per field this operation can set, so the set of fields
// is the set of rules that could apply — a column an update cannot touch has
// no hook here to write by mistake. A nil one is skipped. Every configured
// hook runs, because a rule that fails should not hide the next one, so a
// request reports everything wrong with it.
//
// A hook returns a FieldError to attach the message to a specific field, or
// any other error to fail the request outright.
type RigNotificationSettingUpdateValidator struct {
	// Whose preference it is.
	AccountID func(ctx context.Context, c *RigNotificationSettingValidatorContext, value uuid.UUID) error
	// Null is the default for the channel, which is the second step of the
	// resolution.
	Kind func(ctx context.Context, c *RigNotificationSettingValidatorContext, value *string) error
	// Which channel it answers for.
	Channel func(ctx context.Context, c *RigNotificationSettingValidatorContext, value RigNotificationChannel) error
	// False writes no delivery row at all. Not the same as digest Off, which is
	// about preferring to look rather than be told.
	IsEnabled func(ctx context.Context, c *RigNotificationSettingValidatorContext, value bool) error
	// Immediate sends each on its own; anything else waits for the window and goes
	// out as one message.
	Digest func(ctx context.Context, c *RigNotificationSettingValidatorContext, value RigNotificationDigest) error
	// When to start delivering, in the account time zone. Null means all day. A
	// window that wraps midnight is ordinary: 22:00 to 06:00 is how somebody says
	// "not overnight".
	ActiveFrom func(ctx context.Context, c *RigNotificationSettingValidatorContext, value *time.Time) error
	// When to stop. Outside the window a delivery is held, not dropped: the inbox
	// line exists either way, and a discarded copy makes the badge and the mailbox
	// disagree.
	ActiveUntil func(ctx context.Context, c *RigNotificationSettingValidatorContext, value *time.Time) error
	// ISO weekdays, 1 being Monday. Empty means every day. An array rather than a
	// bitmask because [1,2,3,4,5] is legible in a settings payload and 62 is not.
	ActiveDays func(ctx context.Context, c *RigNotificationSettingValidatorContext, value []int16) error

	// Entity runs after the per-field hooks, for a rule that is about the row
	// rather than about one column.
	Entity func(ctx context.Context, c *RigNotificationSettingValidatorContext) error
}

// RunUpdate implements [dbhook.UpdateValidator]: it runs the service's rules
// against the row this update would produce, with the row as it was available
// for a rule about the change itself.
func (v RigNotificationSettingUpdateValidator) RunUpdate(ctx context.Context, claims tenancy.Claims, i *RigNotificationSettingUpdateInput, prev *RigNotificationSetting) error {
	c := &RigNotificationSettingValidatorContext{
		Values:   i.Merged(prev),
		Claims:   claims,
		previous: *prev,
		isUpdate: true,
		changed:  map[string]bool{},
	}
	c.changed[ColumnRigNotificationSettingAccountID] = i.AccountID.IsSet()
	c.changed[ColumnRigNotificationSettingKind] = i.Kind.Touched()
	c.changed[ColumnRigNotificationSettingChannel] = i.Channel.IsSet()
	c.changed[ColumnRigNotificationSettingIsEnabled] = i.IsEnabled.IsSet()
	c.changed[ColumnRigNotificationSettingDigest] = i.Digest.IsSet()
	c.changed[ColumnRigNotificationSettingActiveFrom] = i.ActiveFrom.Touched()
	c.changed[ColumnRigNotificationSettingActiveUntil] = i.ActiveUntil.Touched()
	c.changed[ColumnRigNotificationSettingActiveDays] = i.ActiveDays.IsSet()

	failed, err := v.run(ctx, c)
	if err != nil {
		return err
	}
	if failed != nil {
		return failed
	}
	return nil
}

